import{_ as t,o as e,c as a,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学日报 | 2026年7月30日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-07-30.md","filePath":"science-log/src/science-daily/2026-07-30.md"}'),r={name:"science-log/src/science-daily/2026-07-30.md"};function u(i,o,s,c,q,d){return e(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="🔬-科学日报-2026年7月30日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年7月30日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年7月30日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年7月30日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 2026-07-30（<strong>事后重建版</strong>简讯 + 共 10 条：科学前沿 5 + AI 前沿 5） 分析日期：2026-07-30 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-05 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-用-概率编码-给蛋白质做减法-raygun-把天然蛋白缩小-10–25" tabindex="-1">1. 用&quot;概率编码&quot;给蛋白质做减法：Raygun 把天然蛋白缩小 10–25% <a class="header-anchor" href="#_1-用-概率编码-给蛋白质做减法-raygun-把天然蛋白缩小-10–25" aria-label="Permalink to &quot;1. 用&quot;概率编码&quot;给蛋白质做减法：Raygun 把天然蛋白缩小 10–25%&quot;">​</a></h3><p><strong>原文</strong>：Devkota 等人提出 Raygun：把任意长度的蛋白编码成固定维度的概率分布而非变长向量，只靠替换率与长度变化两个参数，就能把蛋白缩小 10–25%，同时保留预测结构与功能位点。</p><p><strong>深度扩展</strong>：这项工作由 Kapil Devkota、Daichi Shonai、Joey Mao、Young Su Ko、Wei Wang、Scott Soderling、Ratul Singh 等 7 位作者完成（机构归属未在检索结果中核实），2026 年 7 月 29 日在线发表于 <em>Nature</em>（DOI 10.1038/s41586-026-10842-8）。它要解决的是蛋白质设计里一个长期不对称：自然进化靠数十亿年的替换、插入、删除&quot;从模板造新蛋白&quot;，而计算方法此前无法完整复刻这种<strong>保功能的序列重写</strong>能力。</p><p>关键概念突破在<strong>表示方式</strong>：蛋白质语言模型给出的是每个残基的表征，但序列长度可变，导致不同蛋白之间无法直接运算。Raygun 把一条蛋白编码为固定维度的概率分布（由语言模型嵌入构造的概率编码），于是任意长度的蛋白都落在同一可比较空间里。用户只需调两个旋钮——替换率与长度变化率——就能在保持预测结构完整性与功能位点不变的前提下，压缩 10–25%（部分超过 50%）、扩张到超过天然尺寸，或引入大量序列多样性。研究中还在细胞层面验证了小型化后的功能仍然成立。</p><p>为什么重要：蛋白小型化直接对应药物递送、稳定性和表达成本问题——更小的酶或结合蛋白更容易穿透组织、更易表达纯化、免疫原性更低。更重要的是它把&quot;设计&quot;从逐残基生成变成<strong>在分布空间里连续调参</strong>，这为后续把蛋白改造纳入可批量筛选的流程提供了接口。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 中的蛋白工程/药物设计线索直接相接；其&quot;固定维度概率编码 + 两个控制参数&quot;的思路，与 <code>topics/ai-brain/index.md</code> 里&quot;表征空间可比较性决定能否运算&quot;的论点同构。</p><hr><h3 id="_2-2-110-个着丝粒的全球图谱-着丝粒内部存在-军备竞赛" tabindex="-1">2. 2,110 个着丝粒的全球图谱：着丝粒内部存在&quot;军备竞赛&quot; <a class="header-anchor" href="#_2-2-110-个着丝粒的全球图谱-着丝粒内部存在-军备竞赛" aria-label="Permalink to &quot;2. 2,110 个着丝粒的全球图谱：着丝粒内部存在&quot;军备竞赛&quot;&quot;">​</a></h3><p><strong>原文</strong>：研究组装并刻画了来自 5 大洲、28 个群体的 2,110 个着丝粒，发现突变率有 20 倍差异，动粒位点是着丝粒内突变最快的区域，并提出着丝粒序列与蛋白之间的&quot;军备竞赛&quot;模型。</p><p><strong>深度扩展</strong>：由 Shenghan Gao、Keisuke K. Oshima、Shu-Cheng Chuang、Mark Loftus 等 281 位作者合作完成，2026 年 7 月 29 日在线发表于 <em>Nature</em>（DOI 10.1038/s41586-026-10841-9），属 T2T 之后&quot;重复区基因组学&quot;的代表性大科学产出。着丝粒是保证染色体正确分离的区域，但其高度重复的 α 卫星序列长期让组装与刻画停在&quot;看不清&quot;的状态，个体、群体与演化层面的多样性几乎是空白。</p><p>方法上，团队用为着丝粒定制的生物信息工具，完成 2,110 个着丝粒的组装与注释，识别出 226 种着丝粒单倍型与 1,870 种 α 卫星高阶重复（HOR）变体。结构上，多数着丝粒只有一个动粒位点，但约 6% 为双动粒、不到 1% 为三动粒——这一点用长读长染色质 profiling 与多代遗传得到确认，并显示动粒位置与底层序列/结构紧密相关。</p><p>演化层面是本文最硬的部分：与人类泛基因组联盟（HPRC）的 5,747 个着丝粒比对后发现，着丝粒之间突变率相差可达 20 倍，部分着丝粒带有古人类渗入的证据；在一个四代 28 人家庭中验证了突变率估计，并确认<strong>动粒位点是着丝粒内突变最快的区域</strong>。作者据此提出着丝粒 DNA 与结合蛋白之间的&quot;军备竞赛&quot;（arms race）模型：蛋白要抓住 DNA，DNA 又在快速改写自己。</p><p>为什么重要：着丝粒异常与染色体不分离、非整倍体、部分癌症和生殖失败相关；把&quot;哪里变得最快&quot;定位到动粒位点，等于给出了一个高分辨率的变异热点图谱，也为人造染色体与着丝粒编辑提供了边界条件。</p><p><strong>跨主题关联</strong>：可与 <code>topics/biomedicine/index.md</code> 的基因组/疾病线索衔接；其&quot;快速变异区 ↔ 结合蛋白对抗&quot;的结构，与 <code>topics/cybersecurity/index.md</code> 中攻防共演的逻辑同构。</p><hr><h3 id="_3-转移灶的-免疫荒漠-是癌细胞自己造出来的" tabindex="-1">3. 转移灶的&quot;免疫荒漠&quot;是癌细胞自己造出来的 <a class="header-anchor" href="#_3-转移灶的-免疫荒漠-是癌细胞自己造出来的" aria-label="Permalink to &quot;3. 转移灶的&quot;免疫荒漠&quot;是癌细胞自己造出来的&quot;">​</a></h3><p><strong>原文</strong>：研究整合单细胞与空间多组学，发现静息态 Phgdh^high 播散肿瘤细胞通过 PHGDH 依赖的 H3K27me3 表观沉默关闭趋化因子转录，塑造免疫匮乏微环境，推动肺转移扩张。</p><p><strong>深度扩展</strong>：由 Sun Y、Zhong Y、Liu S 等作者完成，2026 年 7 月 30 日发表于 <em>Science</em>（DOI 10.1126/science.adz7928）。转移是癌症致死的主要环节，但&quot;播散出去的单个细胞如何在新组织里站住脚&quot;一直缺少时空分辨的观测。</p><p>方法上，团队把多模态单细胞测序与空间谱系分析结合，在肝癌小鼠模型与人类转移灶样本中同时追踪播散肿瘤细胞（DTC）与其周围微环境，从&quot;单细胞定植&quot;一路拍到&quot;显性肺转移&quot;。</p><p>核心发现是一个<strong>残余的静息态亚群</strong>：Phgdh 高表达的 DTC 能躲过早期先天免疫清除，并在微转移灶阶段短暂富集。机制链条相当完整——PHGDH（磷酸甘油酸脱氢酶，丝氨酸合成通路关键酶）驱动 H3K27me3 介导的趋化因子转录表观沉默，使局部招募不到免疫细胞，形成&quot;免疫荒漠&quot;，转移克隆才得以扩张。文中还提示 Cx3cr1 相关轴参与其中。</p><p>为什么重要：这提供了一条可干预的表观—代谢交叉靶点。若能在微转移阶段打断&quot;趋化因子沉默&quot;，等于让免疫系统重新看见那些本已潜伏的细胞——比在显性转移后追杀要容易得多。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的肿瘤免疫/代谢重编程线索相接；&quot;通过沉默信号来隐藏自身&quot;这一策略，与 <code>topics/ai-brain/index.md</code> 中&quot;信息不可见即无法被检索/攻击&quot;的结构同构。</p><hr><h3 id="_4-溶酶体衰老图谱-与-溶酶体贮积病-共享的代谢签名" tabindex="-1">4. 溶酶体衰老图谱：与&quot;溶酶体贮积病&quot;共享的代谢签名 <a class="header-anchor" href="#_4-溶酶体衰老图谱-与-溶酶体贮积病-共享的代谢签名" aria-label="Permalink to &quot;4. 溶酶体衰老图谱：与&quot;溶酶体贮积病&quot;共享的代谢签名&quot;">​</a></h3><p><strong>原文</strong>：团队构建了脑、心、肌肉、白色脂肪的多组织溶酶体代谢物衰老图谱，发现衰老溶酶体蓄积甘油磷酸二酯类与胱氨酸，其水平随年龄线性上升且早于机体衰退。</p><p><strong>深度扩展</strong>：由 Puszynska AM、Nguyen TP、Cangelosi AL、Armani A 等作者完成，2026 年 7 月 30 日发表于 <em>Science</em>（DOI 10.1126/science.ady0832）。溶酶体功能下降是衰老的标志之一，但此前很难系统性测量&quot;溶酶体内部到底积累了什么&quot;——因为溶酶体体积小、数量多、分离困难。</p><p>方法上的关键突破是<strong>快速溶酶体分离工具套件</strong>：能在较短时间内拿到较纯的溶酶体组分，从而对脑、心、肌肉、白色脂肪四种组织做代谢物层面的横向比较，构建&quot;溶酶体代谢物衰老图谱&quot;。</p><p>结果有两点很硬：其一，衰老溶酶体一致蓄积<strong>甘油磷酸二酯类（glycerophosphodiesters）与胱氨酸（cystine）</strong>，这两类代谢物正是青少年溶酶体贮积病、Batten 病与胱氨酸病的因果相关分子——等于把&quot;正常衰老&quot;和&quot;罕见遗传病&quot;接到同一条通路上；其二，这些代谢物水平<strong>随年龄线性上升，且上升早于机体整体衰退</strong>，具备生物标志物的时间性质。干预实验显示，热量限制（已知延寿手段）能减轻心与肌肉中的蓄积，但对脑无效，提示脑溶酶体老化对代谢干预相对&quot;免疫&quot;。</p><p>为什么重要：这为&quot;衰老能否用溶酶体代谢物读数来度量&quot;提供了多组织基线，也解释了为何部分溶酶体贮积病药物思路可能外推到普通衰老；同时&quot;脑不受益&quot;这一负结果，对任何宣称全身性抗衰干预的说法都是重要的边界条件。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的衰老生物学线索相接；&quot;线性累积 + 阈值后崩溃&quot;的形态，可与 <code>topics/materials/index.md</code> 中疲劳损伤累积的失效模型类比。</p><hr><h3 id="_5-54-个量子点的硅基量子处理单元-交换型量子比特性能提升一个数量级" tabindex="-1">5. 54 个量子点的硅基量子处理单元：交换型量子比特性能提升一个数量级 <a class="header-anchor" href="#_5-54-个量子点的硅基量子处理单元-交换型量子比特性能提升一个数量级" aria-label="Permalink to &quot;5. 54 个量子点的硅基量子处理单元：交换型量子比特性能提升一个数量级&quot;">​</a></h3><p><strong>原文</strong>：该工作把定制低温 CMOS 控制器、高密度超导带状电缆与低噪声交换型比特器件集成为一套 QPU，芯片为 54 个交换耦合量子点的三轨阵列，可配置出最多 18 个交换型量子比特。</p><p><strong>深度扩展</strong>：由 Michael Abraham、Edwin Acuna、Tower S. Adams 等 256 位作者合作完成，2026 年 7 月 29 日在线发表于 <em>Nature</em>（DOI 10.1038/s41586-026-10754-7）。这是一篇典型的&quot;工程集成&quot;型论文：它不主张某个新物理效应，而是回答硅基路线能否真的走向规模化的三个疑问——噪声够不够低、控制与布线能不能扩展、制造是否与现有半导体工艺兼容。</p><p>系统由三部分组成：定制设计的<strong>低温 CMOS 控制器</strong>（把控制电子学搬进稀释制冷机附近，减少室温到低温的线缆负担）、<strong>高密度超导带状电缆</strong>（解决布线密度）、以及<strong>低噪声交换型（exchange-only）量子比特器件</strong>。量子芯片是 54 个交换耦合量子点的三轨阵列，可配置为最多 18 个交换型量子比特。所谓 exchange-only，指只用交换相互作用操控自旋，无需为每个比特单独做射频寻址——控制信号简单正是它相对超导比特的潜在优势。</p><p>性能上，单比特与双比特纠缠操作的指标比此前交换型的最好水平提升约一个数量级；验证则用了 distance-5 重复码与 distance-2 量子纠错码，并与仿真结果做了细致比对。这说明该系统不只是&quot;能跑门&quot;，而是能承载纠错码所需的重复测量与关联读出。</p><p>为什么重要：量子计算的瓶颈越来越从&quot;物理比特质量&quot;转向&quot;控制与布线的工程代价&quot;。把控制器、线缆、器件作为一个整体系统交付，并给出可用的纠错码验证，是&quot;utility-scale&quot;路线上少见的一次端到端演示。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/index.md</code>、<code>topics/physics/index.md</code> 的量子计算/凝聚态线索相接；&quot;把控制层下移到物理层附近以减少传输代价&quot;这一原则，与 <code>topics/ai-system-architecture/index.md</code> 中缓存/近存计算的思路同构。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-wait-让高频-等着-信号——频段感知的流匹配生成" tabindex="-1">6. WaiT：让高频&quot;等着&quot;信号——频段感知的流匹配生成 <a class="header-anchor" href="#_6-wait-让高频-等着-信号——频段感知的流匹配生成" aria-label="Permalink to &quot;6. WaiT：让高频&quot;等着&quot;信号——频段感知的流匹配生成&quot;">​</a></h3><p><strong>原文</strong>：作者提出 Wavelet-aware image Transformer，用无损小波把生成拆成粗、细两个频段，高频段先保持纯噪声，等粗结构成形后再并入流共同精修；在 ImageNet 512×512 上像素空间 FID 达 1.43，采样算力最多省 50%。</p><p><strong>深度扩展</strong>：由 Krunoslav Lehman Pavasovic、Théophane Vallaeys、Stéphane Mallat 完成，2026 年 7 月 30 日提交于 arXiv（2607.28760）。Mallat 是信号处理与小波理论的奠基级人物（多分辨率分析），这篇正是把&quot;频段层级&quot;这类经典直觉搬进扩散/流匹配生成。</p><p>问题很具体：分辨率越高，全局一致性、局部细节与纹理保真度越难兼顾；而标准流匹配对所有空间频率一视同仁，但<strong>高频段在去噪轨迹上远早于粗结构就与纯噪声无法区分</strong>——等于把算力均匀撒在了信息量不等的地方。</p><p>WaiT 的做法是：用无损小波把图像分成粗、细频带，高频带先&quot;等待&quot;（保持纯噪声，不参与），等粗结构成形后再并流联合精修。配套贡献是对评测的批评：标准 FID 通过激进下采样丢弃了细粒度信息，因此他们提出三轴原生分辨率评测协议。结果：ImageNet 512×512 像素空间 FID 1.43，三轴均 Pareto 最优，采样算力最多省 50%，最大 2B 模型在 ImageNet 上把像素空间模型的 FID 推到 1.3。</p><p>为什么重要：一是&quot;按频段分配算力&quot;是可迁移的通用原则（视频、3D、音频同理）；二是它提醒评测协议本身会掩盖提升——若不换指标，这类改进甚至看不出来。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code> 中&quot;分层/多尺度表征优于扁平表征&quot;的论点直接呼应；小波多分辨率思路亦可回溯到 <code>topics/physics/index.md</code> 的尺度分析传统。</p><hr><h3 id="_7-github-copilot-生产级轨迹首次刻画-3-2m-用户、761m-次-llm-调用" tabindex="-1">7. GitHub Copilot 生产级轨迹首次刻画：3.2M 用户、761M 次 LLM 调用 <a class="header-anchor" href="#_7-github-copilot-生产级轨迹首次刻画-3-2m-用户、761m-次-llm-调用" aria-label="Permalink to &quot;7. GitHub Copilot 生产级轨迹首次刻画：3.2M 用户、761M 次 LLM 调用&quot;">​</a></h3><p><strong>原文</strong>：本文基于 2026 年 6 月采样的 Copilot 轨迹（320 万用户、1,300 万会话、7.61 亿次 LLM 调用、95 万亿 token）做首个生产规模刻画，发现 KV cache 命中率在轮内平均 90%，跨轮边界降至 55%。</p><p><strong>深度扩展</strong>：由 Banruo Liu、Haoran Qiu、Íñigo Goiri 等完成，2026 年 7 月 30 日提交于 arXiv（2608.00101），是少见的&quot;工业界实数&quot;论文。此前关于编程智能体的讨论多基于小规模基准或实验室环境，本文用的是采样自生产环境的真实轨迹。</p><p>最有价值的三个观察：其一，<strong>负载形态不同于聊天</strong>——会话由稀疏的用户发起轮次构成，每一轮展开为几乎总伴随工具执行的自主循环，于是&quot;用户空闲几分钟&quot;与&quot;智能体快速连续调用&quot;交替出现；其二，<strong>KV cache 的经济学被轮边界切开</strong>：轮内命中率平均 90%，跨轮降到 55%，模型切换或上下文压缩后会剧烈失效——这意味着前缀缓存、会话粘性路由与压缩策略的收益需要重新核算；其三，token 消耗、时长、工具调用数均呈长尾，意味着容量规划不能用均值。</p><p>在此基础上他们提出一个轻量级交互设计（论文摘要中被截断，具体形态需见原文），指向&quot;在轮边界与空闲期做调度&quot;的系统优化方向。</p><p>为什么重要：这是把&quot;智能体工作负载&quot;从概念变成可测量对象的一步。对任何要自建 agent 基础设施的人，90%/55% 这两个数字直接决定缓存与调度的投入产出比。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code> 的推理服务/缓存线索强相关，也可挂到 <code>topics/vibe-coding/index.md</code> 的 AI 编程实践；&quot;轮内高命中、跨轮失效&quot;的断裂结构，与 <code>topics/ai-brain/index.md</code> 中&quot;上下文即工作记忆、切换即失忆&quot;的观察同构。</p><hr><h3 id="_8-修-bug-智能体-测试通过-有多少真在测这个-bug-46-不含判别信息" tabindex="-1">8. 修 bug 智能体&quot;测试通过&quot;有多少真在测这个 bug？46% 不含判别信息 <a class="header-anchor" href="#_8-修-bug-智能体-测试通过-有多少真在测这个-bug-46-不含判别信息" aria-label="Permalink to &quot;8. 修 bug 智能体&quot;测试通过&quot;有多少真在测这个 bug？46% 不含判别信息&quot;">​</a></h3><p><strong>原文</strong>：在 110 个任务、643 次 rollout 的 3,730 个事件中，46.0% 的阳性可比事件不含任何 bug 判别信息，23.8% 的基线 rollout 完全靠这类证据收工。</p><p><strong>深度扩展</strong>：由 Xiaonan Xu、Wenjing Wu 完成，2026 年 7 月 30 日提交于 arXiv（2607.28871）。它问的是一个很少被质疑的环节：修复智能体跑测试、看到 pass，就把这个 pass 当作&quot;我的补丁修好了这个 bug&quot;的证据——这个推断何时成立？</p><p>方法是 BSG-VA（buggy-state / candidate-state / gold-fix validation analysis）：在精确的工作树状态下捕获每条验证命令，抽出 test-only 补丁，然后把同一条命令分别重放到原始 buggy 代码（B）、候选状态（S）与开发者金修（G）上。三者结果一比对，就能给每个事件判定证据角色——从&quot;与金修一致且能判别 bug&quot;到&quot;仅回归&quot;再到&quot;误导&quot;。</p><p>数据：110 个任务、643 次 rollout、3,730 个事件；46.0% 的阳性可比事件<strong>不含任何 bug 判别信息</strong>（也就是说，这些测试在 bug 存在时也会通过），23.8% 的基线 rollout 的全部阳性证据都属于这一类——它们的&quot;修好了&quot;其实是空证。三段式实验检验补救：把 B 重放结果回灌给智能体，证据不足即收工的比例相对注意力匹配对照组下降 7.8 个百分点（p = 0.0029），bug 判别能力上升。</p><p>为什么重要：这是把&quot;验证&quot;本身当作可审计对象。对任何自动化闭环（agent 自测、CI 门禁、自动合并），&quot;测试通过&quot;不是证据，&quot;测试在 bug 存在时会失败&quot;才是证据。</p><p><strong>跨主题关联</strong>：与 <code>topics/vibe-coding/index.md</code>、<code>topics/ai-system-architecture/index.md</code> 的 agent 工程实践相接；&quot;缺少对照就无信息&quot;这一逻辑，与 <code>topics/ai-brain/index.md</code> 中&quot;没有反例的信念不可证伪&quot;同构。</p>',67)])])}const l=t(r,[["render",u]]);export{p as __pageData,l as default};
